import { GroupOverview } from 'kafkajs';

declare class CyberSend {
    private producer;
    private registry;
    private kafka;
    private producerRunning;
    private sendTopic;
    constructor(psw: string, task_name: string);
    private manageProducerConnection;
    startProducer(): Promise<void>;
    sendMessages(dataArray: {
        username: string;
        message_send: string;
    }[]): Promise<{
        error?: string;
        details?: any;
    }>;
    sendChat(data: {
        user_id: number;
        api_server: string;
    }): Promise<{
        error?: string;
        details?: any;
    }>;
    getBestTopic(topics: string[]): Promise<void>;
}

declare class CyberReceive {
    private registry;
    private kafka;
    private consumer;
    constructor(psw: string, group: string);
    getChat(callback: (message: {
        user_id: number;
        server_id: number;
    }) => void, concurrency?: number): Promise<void>;
    getMessage(callback: (message: {
        username: string;
        title: string;
        level: string;
        detail: string;
    }) => void, concurrency?: number): Promise<void>;
}

declare class CyberAdmin {
    private kafka;
    private admin;
    private registry;
    constructor(psw: string);
    private updateSchema;
    updateSchemas(schemaPaths: string[]): Promise<void>;
    createTopics(topics: string[]): Promise<{
        success?: boolean;
        message?: string;
        error?: string;
        details?: any;
    }>;
    deleteTopics(topics: string[]): Promise<{
        success?: boolean;
        message?: string;
        error?: string;
        details?: any;
    }>;
    createPartitions(topic: string, partitions: number): Promise<{
        success?: boolean;
        message?: string;
        error?: string;
        details?: any;
    }>;
    listAllTopics(): Promise<{
        success?: boolean;
        topics?: string[];
        error?: string;
        details?: any;
    }>;
    listAllGroups(): Promise<{
        success?: boolean;
        groups?: GroupOverview[];
        error?: string;
        details?: any;
    }>;
}

interface PartitionOffsets {
    [partition: string]: {
        offset: number;
        high: number;
        low: number;
    };
}

export { CyberAdmin, CyberReceive, CyberSend, type PartitionOffsets };
